  public duplicateProduct(id: string): Product | undefined {
    const prod = this.state.products.find((p) => p.id === id);
    if (!prod) return;

    const copy: Product = {
      ...prod,
      id: `prod-${Date.now()}`,
      sku: `${prod.sku}-COPY`,
      barcode: `625${Math.floor(1000000000 + Math.random() * 9000000000)}`,
